def _phase_buy_crops(day):
    """Which crops the market should be stocking this phase."""
    if day < 6:
        return ["MELON", "WHEAT", "CARROT"]
    if day < 12:
        # Wave-2 melon seeds are time-critical (must be planted by ~day 13 to
        # mature), so they outrank strawberry seed stocking on days 6-11.
        return ["MELON", "STRAWBERRY", "WHEAT"]
    return ["STRAWBERRY", "WHEAT"]


