# quadratic, strawberries/milk/wool are linear), so we pace premium sales to
# roughly match town consumption instead of dumping a full harvest at once.
# Shed overflow handles any surplus. Reset best-effort on day change.
_DAILY_SOLD = {"day": -1, "MELON": 0, "STRAWBERRY": 0, "MILK": 0, "WOOL": 0}

PREMIUM_DAILY_BUDGET = {
