# ==========================================================================
# HELPER FUNCTIONS
# ==========================================================================

def _pass():
    return {"farmer": ["PASS"], "hands": [], "market": []}

def _safe_get(d, key, default):
    if isinstance(d, dict): return d.get(key, default)
    return default

def _int(value, default=0):
    try: return int(value) if value is not None else default
    except: return default

def _float(value, default=0.0):
    try: return float(value) if value is not None else default
    except: return default

def _is_sequence(obj): return isinstance(obj, (list, tuple))

def _in_bounds(tiles, x, y):
    try: return 0 <= y < len(tiles) and 0 <= x < len(tiles[y])
    except: return False

def _step_towards(fx, fy, tx, ty):
    if tx < fx: return ["WEST"]
    if tx > fx: return ["EAST"]
    if ty < fy: return ["NORTH"]
    if ty > fy: return ["SOUTH"]
    return ["PASS"]

def _manhattan(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])

def _fib_cost(n):
    a,b = 1,1
    for _ in range(max(0,n)): a,b = b, a+b
    return a

def _quadrant(x,y,tiles):
    half = max(1, len(tiles)//2)
    if x < half and y < half: return "NW"
    if x >= half and y < half: return "NE"
    if x < half and y >= half: return "SW"
    return "SE"

def _is_plant(tile): return isinstance(tile,dict) and _safe_get(tile,"kind","") == "PLANT"
def _is_weed(tile): return isinstance(tile,dict) and _safe_get(tile,"kind","") == "WEED"

def _plant_ready(tile, day):
    crop = _safe_get(tile,"crop","WHEAT")
    yu = _int(_safe_get(tile,"yield_units",0),0)
    pd = _int(_safe_get(tile,"planted_day",0),0)
    age = max(0, day - pd)
    if crop in ONGOING_CROPS: return yu > 0
    md = CROP_MAX_DAY.get(crop,4)
    my = CROP_MAX_YIELD.get(crop,4)
    return age >= md or yu >= my

def _scan_active_crops(tiles):
    active = {}
    if not _is_sequence(tiles): return active
    for row in tiles:
        if not _is_sequence(row): continue
        for tile in row:
            if _is_plant(tile):
                c = _safe_get(tile,"crop","WHEAT")
                active[c] = active.get(c,0) + 1
    return active

def _count_placed_animals(tiles):
    cnt = 0
    if not _is_sequence(tiles): return 0
    for row in tiles:
        if not _is_sequence(row): continue
        for tile in row:
            if isinstance(tile,dict) and tile.get("kind")=="PASTURE" and tile.get("animal"):
                cnt += 1
    return cnt

def _count_empty_pastures(tiles):
    cnt = 0
    if not _is_sequence(tiles): return 0
    for row in tiles:
        if not _is_sequence(row): continue
        for tile in row:
            if isinstance(tile,dict) and tile.get("kind")=="PASTURE" and not tile.get("animal"):
                cnt += 1
    return cnt

def _count_pastures(tiles):
    cnt = 0
    if not _is_sequence(tiles): return 0
    for row in tiles:
        if not _is_sequence(row): continue
        for tile in row:
            if isinstance(tile,dict) and tile.get("kind")=="PASTURE":
                cnt += 1
    return cnt

def _pasture_tiles(unlocked_set):
    res = []
    for q in ["NW","NE","SW"]:
        if q in unlocked_set:
            res.extend(HARD_PASTURE_TILES.get(q,[]))
    return res

def _desired_hands(day, money, active_crops, placed_animals):
    if day >= LIQUIDATION_DAY: return 2
    if not isinstance(active_crops, dict): active_crops = {}
    total = sum(active_crops.values())
    if day <= 1: base = 5
    elif day <= 5: base = 3 + total//6 + placed_animals//4
    elif day <= 10: base = 5 + total//5 + placed_animals//3
    else: base = 7 + total//5 + placed_animals//2
    floor = 3 if day <=5 else 2
    return max(floor, min(HANDS_CAP, base))

def _sellable_inventory(item, shed, global_inventory, day, placed_animals):
    sq = _int(_safe_get(shed,item,0),0)
    if sq <= 0: return 0
    if item == "WHEAT":
        gq = _int(global_inventory.get("WHEAT",0),0)
        if day >= 29: keep = 0
        elif day >= LIQUIDATION_DAY: keep = max(0, placed_animals*2)
        else: keep = max(0, placed_animals*2 + 3)
        excess = gq - keep
        if excess <= 0: return 0
        return min(sq, excess)
    if item == "FERTILIZER":
        gq = _int(global_inventory.get("FERTILIZER",0),0)
        if day >= LIQUIDATION_DAY: keep = 0
        elif not ENABLE_FERTILIZER_CROP_USE: keep = 5
        elif day < 20: keep = 24
        else: keep = 8
        excess = gq - keep
        if excess <= 0: return 0
        return min(sq, excess)
    return sq

def _crop_cap(crop, planning_workers, unlocked_cnt):
    if crop == "MELON": return min(30, 8 + planning_workers*2 + (unlocked_cnt-1)*5)
    if crop == "STRAWBERRY": return min(36, 8 + planning_workers*2 + (unlocked_cnt-1)*6)
    if crop == "CARROT": return min(40, 6 + planning_workers + (unlocked_cnt-1)*8)
    if crop == "WHEAT": return min(40, 6 + planning_workers + (unlocked_cnt-1)*8)
    if crop == "TOMATO": return min(30, 6 + planning_workers + (unlocked_cnt-1)*6)
    return 0

def _phase_buy_crops(day):
    if day < 6: return ["MELON","WHEAT","CARROT"]
    if day < 12: return ["MELON","STRAWBERRY","WHEAT"]
    return ["STRAWBERRY","WHEAT"]

def _choose_target_crops(day, hour, money, seeds, active_crops, market_inventory,
                         planning_workers, unlocked_cnt):
    days_left = max(0,30-day)
    if days_left < 4: return []
    if day < 6: priority = ["MELON","WHEAT","CARROT"]
    elif day < 12: priority = ["STRAWBERRY","MELON","WHEAT"]
    else:
        if days_left >= MIN_PLANT_DAYS.get("MELON",11) and _int(_safe_get(seeds,"MELON",0),0)>0:
            priority = ["MELON","STRAWBERRY","WHEAT"]
        else:
            priority = ["STRAWBERRY","WHEAT"]
    res = []
    for crop in priority:
        if days_left < MIN_PLANT_DAYS.get(crop,5): continue
        if _int(_safe_get(seeds,crop,0),0) > 0:
            active = active_crops.get(crop,0)
            cap = _crop_cap(crop, planning_workers, unlocked_cnt)
            if active < cap: res.append(crop)
    return res

def _plant_budget(target_crops, seeds, active_crops, planning_workers, unlocked_cnt):
    budget = {}
    for crop in target_crops:
        have = _int(_safe_get(seeds,crop,0),0)
        active = active_crops.get(crop,0)
        cap = _crop_cap(crop, planning_workers, unlocked_cnt)
        budget[crop] = max(0, min(have, cap - active))
    return budget

# --- DYNAMIC PRICING ENGINE ---
def _get_price(item, inv):
    I0 = 10000
    base = BASE_PRICE.get(item, 1)
    params = {
        "WHEAT": (400, "sqrt", 0.80, "log", 0.20),
        "CARROT": (450, "log", 0.20, "sqrt", 0.70),
        "TOMATO": (200, "linear", 0.40, "sqrt", 0.60),
        "STRAWBERRY": (100, "sqrt", 0.70, "linear", 1.60),
        "MELON": (300, "log", 0.20, "sq", 3.60),
        "EGG": (332, "linear", 0.40, "log", 0.20),
        "MILK": (122, "sqrt", 0.60, "linear", 1.60),
        "WOOL": (105, "log", 0.20, "sq", 3.20),
        "FERTILIZER": (200, "linear", 0.40, "linear", 0.40),
    }
    if item not in params: return base
    T, bf, bt, af, at = params[item]

    if inv < I0:
        func, tgt = bf, bt
        sign = 1
    else:
        func, tgt = af, at
        sign = -1

    def f(x, func_type):
        if func_type == "linear": return x
        if func_type == "sq": return x**2
        if func_type == "sqrt": return math.sqrt(x)
        if func_type == "log": return math.log(x + 1)
        if func_type == "log10": return math.log10(x + 1)
        return 0

    f_T = f(T, func)
    f_diff = f(abs(inv - I0), func)

    amp = (tgt * base / f_T) if f_T > 0 else 0
    price = base + sign * amp * f_diff
    return max(1, round(price))

# ==========================================================================
# TASK GENERATION
# ==========================================================================

def _generate_tasks(tiles, day, hour, target_crops, plant_budget, new_plant_limits,
                    shed, unit_inventories, unlocked_set, expected_workers):
    tasks = []
    planted_this_turn = {}
    if not _is_sequence(tiles): return tasks

    shed_cows = _int(_safe_get(shed,"COW",0),0)
    shed_sheep = _int(_safe_get(shed,"SHEEP",0),0)
    shed_wheat = _int(_safe_get(shed,"WHEAT",0),0)
    shed_fert = _int(_safe_get(shed,"FERTILIZER",0),0)
    c_cow = c_sheep = c_wheat = c_fert = 0
    for inv in unit_inventories:
        if isinstance(inv,dict):
            c_cow += _int(inv.get("COW",0),0)
            c_sheep += _int(inv.get("SHEEP",0),0)
            c_wheat += _int(inv.get("WHEAT",0),0)
            c_fert += _int(inv.get("FERTILIZER",0),0)

    total_cows = shed_cows + c_cow
    total_sheep = shed_sheep + c_sheep
    empty_past = _count_empty_pastures(tiles)
    total_past = _count_pastures(tiles)
    needed_stables = min(MAX_ANIMALS, total_cows + total_sheep)

    unwatered = sum(1 for row in tiles if _is_sequence(row)
                    for t in row if _is_plant(t) and not _safe_get(t,"watered_today",False))

    plant_capacity = max(8, expected_workers*4)
    pasture_set = _pasture_tiles(unlocked_set)

    cows2place = total_cows
    sheep2place = total_sheep
    plantable = []

    for y, row in enumerate(tiles):
        if not _is_sequence(row): continue
        for x, tile in enumerate(row):
            if tile == "LOCKED": continue
            pos = (x,y)

            if tile is None:
                if pos in pasture_set:
                    if ENABLE_ANIMALS and total_past < needed_stables and total_cows+total_sheep > 0:
                        q = _quadrant(x,y,tiles)
                        if q in unlocked_set:
                            tasks.append({
                                "pos": pos, "type": "BUILD_PASTURE",
                                "priority": PRIORITY_BUILD,
                                "tokens": ["BUILD_PASTURE"],
                            })
                    continue          
                if target_crops:
                    plantable.append(pos)
                continue

            if _is_weed(tile):
                tasks.append({"pos": pos, "type": "DIG", "priority": PRIORITY_DIG, "tokens": ["DIG"]})
                continue

            if isinstance(tile, dict) and tile.get("kind") == "PASTURE":
                animal = tile.get("animal")
                if animal:
                    if not tile.get("fed_today",False):
                        pr = PRIORITY_CRITICAL_SURVIVAL if _int(tile.get("consecutive_unfed",0),0)>=1 else PRIORITY_PLACE
                        tasks.append({"pos": pos, "type": "FEED", "priority": pr,
                                      "tokens": ["FEED"], "req": "WHEAT"})
                    if not tile.get("cared_today",False):
                        tasks.append({"pos": pos, "type": "CARE", "priority": PRIORITY_CARE,
                                      "tokens": ["CARE"]})
                    if tile.get("yield_units",0) > 0:
                        tasks.append({"pos": pos, "type": "HARVEST_ANIMAL", "priority": PRIORITY_HARVEST,
                                      "tokens": ["HARVEST"]})
                    # Fertilizer is only available at end of day
                    if tile.get("fertilizer_available",False) and hour >= 18:
                        tasks.append({"pos": pos, "type": "COLLECT_FERTILIZER", "priority": PRIORITY_COLLECT_FERT,
                                      "tokens": ["COLLECT_FERTILIZER"]})
                else:
                    if cows2place > 0:
                        tasks.append({"pos": pos, "type": "PLACE", "priority": PRIORITY_PLACE,
                                      "tokens": ["PLACE","COW"], "req": "COW"})
                        cows2place -= 1
                    elif sheep2place > 0:
                        tasks.append({"pos": pos, "type": "PLACE", "priority": PRIORITY_PLACE,
                                      "tokens": ["PLACE","SHEEP"], "req": "SHEEP"})
                        sheep2place -= 1
                continue

            if _is_plant(tile):
                if _plant_ready(tile, day):
                    tasks.append({"pos": pos, "type": "HARVEST", "priority": PRIORITY_HARVEST,
                                  "tokens": ["HARVEST"]})
                else:
                    watered = bool(_safe_get(tile,"watered_today",False))
                    if not watered:
                        age = max(0, day - _int(_safe_get(tile,"planted_day",0),0))
                        consec = _int(_safe_get(tile,"consecutive_unwatered",0),0)
                        if consec >= 1: wp = PRIORITY_CRITICAL_SURVIVAL
                        elif age == 0: wp = PRIORITY_HARVEST
                        else: wp = PRIORITY_PLANT + 20
                        tasks.append({"pos": pos, "type": "WATER", "priority": wp,
                                      "tokens": ["WATER"]})
                    if ENABLE_FERTILIZER_CROP_USE:
                        crop = _safe_get(tile,"crop","WHEAT")
                        age = max(0, day - _int(_safe_get(tile,"planted_day",0),0))
                        can_fert = False
                        if crop=="MELON" and 5<=age<=7: can_fert=True
                        elif crop=="STRAWBERRY" and 8<=age<=10: can_fert=True
                        elif crop=="WHEAT" and 2<=age<=4: can_fert=True
                        elif crop=="CARROT" and age==2: can_fert=True

                        # Removed 'and watered' to allow same-day application
                        if can_fert:
                            tasks.append({"pos": pos, "type": "FERTILIZE", "priority": PRIORITY_FERTILIZE,
                                          "tokens": ["FERTILIZE"], "req": "FERTILIZER"})
                continue

    if plantable and target_crops:
        magnet_plantable = [p for p in plantable if p in MAGNET_TILES]
        plantable = [p for p in plantable if p not in MAGNET_TILES]

        for pos in magnet_plantable:
            if unwatered >= plant_capacity: break
            for crop in target_crops:
                if planted_this_turn.get(crop,0) < plant_budget.get(crop,0):
                    limit = new_plant_limits.get(crop, 999)
                    if planted_this_turn.get(crop,0) < limit:
                        tasks.append({
                            "pos": pos, "type": "PLANT", "crop": crop,
                            "priority": PRIORITY_PLANT,
                            "tokens": ["PLANT", crop],
                        })
                        planted_this_turn[crop] = planted_this_turn.get(crop,0) + 1
                        unwatered += 1
                        break

        corner_plantable = [p for p in plantable if p in _CORNER_TILE_SET]
        for pos in corner_plantable[:]:   
            if unwatered >= plant_capacity: break
            for crop in target_crops:
                if planted_this_turn.get(crop,0) < plant_budget.get(crop,0):
                    limit = new_plant_limits.get(crop, 999)
                    if planted_this_turn.get(crop,0) < limit:
                        tasks.append({
                            "pos": pos, "type": "PLANT", "crop": crop,
                            "priority": PRIORITY_PLANT,
                            "tokens": ["PLANT", crop],
                        })
                        planted_this_turn[crop] = planted_this_turn.get(crop,0) + 1
                        unwatered += 1
                        plantable.remove(pos)
                        break

        plantable.sort(key=lambda p: _manhattan(p, SHED_POS))
        for pos in plantable:
            if unwatered >= plant_capacity: break
            for crop in target_crops:
                if planted_this_turn.get(crop,0) < plant_budget.get(crop,0):
                    limit = new_plant_limits.get(crop, 999)
                    if planted_this_turn.get(crop,0) < limit:
                        tasks.append({
                            "pos": pos, "type": "PLANT", "crop": crop,
                            "priority": PRIORITY_PLANT,
                            "tokens": ["PLANT", crop],
                        })
                        planted_this_turn[crop] = planted_this_turn.get(crop,0) + 1
                        unwatered += 1
                        break

    if ENABLE_ANIMALS and empty_past > 0:
        slots = empty_past
        for _ in range(min(shed_cows, slots)):
            tasks.append({"pos": SHED_POS, "type": "PICKUP", "priority": PRIORITY_PLACE,
                          "tokens": ["PICKUP","COW",1]})
            slots -= 1
        for _ in range(min(shed_sheep, slots)):
            tasks.append({"pos": SHED_POS, "type": "PICKUP", "priority": PRIORITY_PLACE,
                          "tokens": ["PICKUP","SHEEP",1]})
            slots -= 1

    need_feed = sum(1 for row in tiles if _is_sequence(row)
                    for t in row if isinstance(t,dict) and t.get("kind")=="PASTURE"
                    and t.get("animal") and not t.get("fed_today",False))
    if need_feed > 0 and shed_wheat > 0 and c_wheat < need_feed:
        tasks.append({"pos": SHED_POS, "type": "PICKUP", "priority": PRIORITY_CRITICAL_SURVIVAL,
                      "tokens": ["PICKUP","WHEAT", min(shed_wheat, need_feed)]})

    if ENABLE_FERTILIZER_CROP_USE and shed_fert > 0 and c_fert < 4:
        tasks.append({"pos": SHED_POS, "type": "PICKUP", "priority": PRIORITY_FERTILIZE,
                      "tokens": ["PICKUP","FERTILIZER", min(shed_fert,4)]})

    return tasks

