def _default_action(unit_pos, tiles):
    x,y = unit_pos
    if not _in_bounds(tiles,x,y): return ["PASS"]
    tile = tiles[y][x]
    if tile == "LOCKED":
        half = max(1,len(tiles)//2)
        return _step_towards(x,y,half-1,half-1)
    return ["PASS"]

CLAIM_BONUS = 3000
CLAIM_STEAL_PENALTY = 2000

def _task_key(task):
    pos = task.get("pos")
    if not _is_sequence(pos) or len(pos)<2: return None
    return (int(pos[0]), int(pos[1]), task.get("type",""), str(task.get("crop","")))

def _assign_tasks_zoned(tasks, unit_positions, tiles, unlocked_set, plant_budget,
                        unit_inventories, target_crops, seeds, group_assignments, day=-1):
    global _TASK_CLAIMS
    active_quadrants = [q for q in ["NW","NE","SW","SE"] if q in unlocked_set]
    if not active_quadrants: active_quadrants = ["NW"]

    if _TASK_CLAIMS["day"] != day:
        _TASK_CLAIMS.update({"day": day, "claims": {}})
    claims = _TASK_CLAIMS["claims"]
    valid_keys = {_task_key(t) for t in tasks if _task_key(t) is not None}
    claims = {k:v for k,v in claims.items() if k in valid_keys}
    new_claims = {}

    ANIMAL_TASK_TYPES = {"BUILD_PASTURE", "FEED", "CARE", "PLACE",
                         "HARVEST_ANIMAL", "COLLECT_FERTILIZER", "PICKUP"}
    CROP_TASK_TYPES = {"PLANT", "WATER", "HARVEST", "FERTILIZE", "DIG"}
    FARMER_ANIMAL_BONUS = 8000
    FARMER_CROP_PENALTY = -2000

    tasks_sorted = sorted(tasks, key=lambda t: t.get("priority",0), reverse=True)

    worker_allowed_tasks = {}   
    worker_group_tiles = {}     
    for group_name, widx in group_assignments.items():
        if widx < len(unit_positions):
            group_tiles = set(CORNER_GROUPS.get(group_name, []))
            worker_group_tiles[widx] = group_tiles
            allowed = [t for t in tasks_sorted if tuple(t.get("pos", (-1,-1))) in group_tiles]
            worker_allowed_tasks[widx] = allowed

    tile_map = {}
    for t in tasks_sorted:
        p = t.get("pos")
        if p is not None: tile_map.setdefault(p,[]).append(t)

    unit_actions = [None]*len(unit_positions)
    assigned_pos = set()
    assigned_plants = {}
    unit_types = ["PASS"]*len(unit_positions)
    unit_prios = [0]*len(unit_positions)
    unit_cnt = max(1, len(unit_positions))

    for idx, upos in enumerate(unit_positions):
        if idx in worker_group_tiles:                
            group_tiles = worker_group_tiles[idx]
            if upos in tile_map:
                for task in tile_map[upos]:
                    if task["pos"] in assigned_pos: continue
                    if tuple(task["pos"]) not in group_tiles: continue
                    req = task.get("req")
                    if req is not None:
                        inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                        if _int(inv.get(req,0),0) <= 0: continue
                    unit_actions[idx] = task["tokens"]
                    assigned_pos.add(task["pos"])
                    if task.get("type") == "PLANT":
                        crop = task.get("crop")
                        assigned_plants[crop] = assigned_plants.get(crop,0) + 1
                    unit_types[idx] = task.get("type","")
                    unit_prios[idx] = task.get("priority",0)
                    break
            continue   

        if idx == 0:   
            if upos in tile_map:
                for task in tile_map[upos]:
                    if task["pos"] in assigned_pos: continue
                    req = task.get("req")
                    if req is not None:
                        inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                        if _int(inv.get(req,0),0) <= 0: continue
                    unit_actions[idx] = task["tokens"]
                    assigned_pos.add(task["pos"])
                    if task.get("type") == "PLANT":
                        crop = task.get("crop")
                        assigned_plants[crop] = assigned_plants.get(crop,0) + 1
                    unit_types[idx] = task.get("type","")
                    unit_prios[idx] = task.get("priority",0)
                    break
            continue

        if upos in tile_map:
            for task in tile_map[upos]:
                if tuple(task["pos"]) in _CORNER_TILE_SET: continue   
                if task["pos"] in assigned_pos: continue
                req = task.get("req")
                if req is not None:
                    inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                    if _int(inv.get(req,0),0) <= 0: continue
                unit_actions[idx] = task["tokens"]
                assigned_pos.add(task["pos"])
                if task.get("type") == "PLANT":
                    crop = task.get("crop")
                    assigned_plants[crop] = assigned_plants.get(crop,0) + 1
                unit_types[idx] = task.get("type","")
                unit_prios[idx] = task.get("priority",0)
                break

    for idx, upos in enumerate(unit_positions):
        if idx != 0: continue
        if unit_actions[idx] is not None: continue

        best, best_score = None, -10**9
        for task in tasks_sorted:
            tpos = task.get("pos")
            if not _is_sequence(tpos) or len(tpos)<2: continue
            if tuple(tpos) in _CORNER_TILE_SET: continue      
            if tpos in assigned_pos: continue
            if task.get("type")=="PLANT":
                crop = task.get("crop")
                if assigned_plants.get(crop,0) >= plant_budget.get(crop,0): continue
            req = task.get("req")
            if req is not None:
                inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                if _int(inv.get(req,0),0) <= 0: continue

            dist = _manhattan(upos, tpos)
            q = _quadrant(tpos[0], tpos[1], tiles)
            home = active_quadrants[idx % len(active_quadrants)]
            second = active_quadrants[(idx+1)%len(active_quadrants)] if len(active_quadrants)>1 else home

            score = task.get("priority",0)*1000 - dist*50

            ttype = task.get("type","")
            if ttype in ANIMAL_TASK_TYPES or (ttype == "PICKUP" and task.get("req") in ("COW","SHEEP","GOOSE")):
                score += FARMER_ANIMAL_BONUS
            elif ttype in CROP_TASK_TYPES:
                score += FARMER_CROP_PENALTY

            k = _task_key(task)
            if k is not None:
                claimer = claims.get(k)
                if claimer == idx: score += CLAIM_BONUS
                elif claimer is not None: score -= CLAIM_STEAL_PENALTY
            if q == home: score += 500
            elif q == second: score += 200
            elif q in unlocked_set: pass
            else: score -= 10000

            if score > best_score:
                best_score = score
                best = task

        if best is not None:
            assigned_pos.add(best["pos"])
            if best.get("type")=="PLANT":
                crop = best.get("crop")
                assigned_plants[crop] = assigned_plants.get(crop,0)+1
            k = _task_key(best)
            if k is not None: new_claims[k] = idx
            unit_types[idx] = best.get("type","")
            unit_prios[idx] = best.get("priority",0)
            if upos == best["pos"]:
                unit_actions[idx] = best["tokens"]
            else:
                unit_actions[idx] = _step_towards(upos[0],upos[1],best["pos"][0],best["pos"][1])

    for idx, upos in enumerate(unit_positions):
        if idx not in worker_allowed_tasks: continue
        if unit_actions[idx] is not None: continue

        allowed_tasks = worker_allowed_tasks[idx]
        best, best_score = None, -10**9

        for task in allowed_tasks:
            tpos = task.get("pos")
            if not _is_sequence(tpos) or len(tpos)<2: continue
            if tpos in assigned_pos: continue
            if task.get("type")=="PLANT":
                crop = task.get("crop")
                if assigned_plants.get(crop,0) >= plant_budget.get(crop,0): continue
            req = task.get("req")
            if req is not None:
                inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                if _int(inv.get(req,0),0) <= 0: continue

            dist = _manhattan(upos, tpos)
            score = task.get("priority",0)*1000 - dist*50

            if score > best_score:
                best_score = score
                best = task

        if best is not None:
            assigned_pos.add(best["pos"])
            if best.get("type")=="PLANT":
                crop = best.get("crop")
                assigned_plants[crop] = assigned_plants.get(crop,0)+1
            unit_types[idx] = best.get("type","")
            unit_prios[idx] = best.get("priority",0)
            if upos == best["pos"]:
                unit_actions[idx] = best["tokens"]
            else:
                unit_actions[idx] = _step_towards(upos[0],upos[1],best["pos"][0],best["pos"][1])
        else:
            unit_actions[idx] = ["PASS"]

    for idx, upos in enumerate(unit_positions):
        if idx == 0: continue                     
        if idx in worker_allowed_tasks: continue  
        if unit_actions[idx] is not None: continue

        best, best_score = None, -10**9
        for task in tasks_sorted:
            tpos = task.get("pos")
            if not _is_sequence(tpos) or len(tpos)<2: continue
            if tuple(tpos) in _CORNER_TILE_SET: continue   
            if tpos in assigned_pos: continue
            if task.get("type")=="PLANT":
                crop = task.get("crop")
                if assigned_plants.get(crop,0) >= plant_budget.get(crop,0): continue
            req = task.get("req")
            if req is not None:
                inv = unit_inventories[idx] if idx < len(unit_inventories) else {}
                if _int(inv.get(req,0),0) <= 0: continue

            dist = _manhattan(upos, tpos)
            q = _quadrant(tpos[0], tpos[1], tiles)
            home = active_quadrants[idx % len(active_quadrants)]
            second = active_quadrants[(idx+1)%len(active_quadrants)] if len(active_quadrants)>1 else home

            score = task.get("priority",0)*1000 - dist*50

            if task.get("type") == "PLANT" and tpos in MAGNET_TILES and dist == 1:
                score += 50000

            k = _task_key(task)
            if k is not None:
                claimer = claims.get(k)
                if claimer == idx: score += CLAIM_BONUS
                elif claimer is not None: score -= CLAIM_STEAL_PENALTY
            if q == home: score += 500
            elif q == second: score += 200
            elif q in unlocked_set: pass
            else: score -= 10000
            if q == home:
                tile_owner = (tpos[0]*7 + tpos[1]*13) % unit_cnt
                if idx == tile_owner: score += 300
                elif idx == (tile_owner+1)%unit_cnt: score += 100

            if score > best_score:
                best_score = score
                best = task

        if best is not None:
            assigned_pos.add(best["pos"])
            if best.get("type")=="PLANT":
                crop = best.get("crop")
                assigned_plants[crop] = assigned_plants.get(crop,0)+1
            k = _task_key(best)
            if k is not None: new_claims[k] = idx
            unit_types[idx] = best.get("type","")
            unit_prios[idx] = best.get("priority",0)
            if upos == best["pos"]:
                unit_actions[idx] = best["tokens"]
            else:
                unit_actions[idx] = _step_towards(upos[0],upos[1],best["pos"][0],best["pos"][1])

    for idx in range(len(unit_positions)):
        if unit_actions[idx] is not None: continue

        upos = unit_positions[idx]
        x, y = upos

        group_tiles = None
        for gname, widx in group_assignments.items():
            if widx == idx:
                group_tiles = set(CORNER_GROUPS.get(gname, []))
                break

        planted = False
        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            nx, ny = x+dx, y+dy
            if not _in_bounds(tiles, nx, ny): continue
            adj_pos = (nx, ny)

            if group_tiles is not None and adj_pos not in group_tiles:
                continue
            if group_tiles is None and adj_pos in _CORNER_TILE_SET:
                continue

            adj_tile = tiles[ny][nx]
            if adj_tile is None and adj_pos not in assigned_pos:
                for crop in target_crops:
                    if seeds.get(crop,0) > 0 and assigned_plants.get(crop,0) < plant_budget.get(crop,9999):
                        unit_actions[idx] = _step_towards(x, y, nx, ny)
                        assigned_pos.add(adj_pos)
                        assigned_plants[crop] = assigned_plants.get(crop,0) + 1
                        unit_types[idx] = "PLANT"
                        unit_prios[idx] = PRIORITY_PLANT
                        planted = True
                        break
            if planted:
                break

        if not planted:
            unit_actions[idx] = _default_action(unit_positions[idx], tiles)

    _TASK_CLAIMS["claims"] = new_claims
    return unit_actions, unit_types, unit_prios

# ==========================================================================
# MAIN AGENT
# ==========================================================================

def agent(obs):
    global _DAILY_SOLD, _TASK_CLAIMS, _GROUP_ASSIGNMENTS
    if obs.get("step",0) == 0: _reset_state()
    try:
        if not isinstance(obs,dict): return _pass()

        player = _int(obs.get("player",0),0)
        day = _int(obs.get("day",0),0)
        hour = _int(obs.get("hour",0),0)

        farms = obs.get("farms",[])
        private = obs.get("private",{})
        if not farms or player>=len(farms): return _pass()
        me = farms[player]
        if not isinstance(me,dict): return _pass()

        money = _float(me.get("money",0),0)
        tiles = me.get("tiles",[])
        farmer = me.get("farmer",[0,0])
        hands = me.get("hands",[])
        unlocked_quads = me.get("unlocked_quadrants",["NW"])
        hires_today = _int(me.get("hires_today",0),0)

        unlocked_cnt = max(1,len(unlocked_quads))
        unlocked_set = set(unlocked_quads)

        if not _is_sequence(tiles) or len(farmer)<2: return _pass()
        if not _is_sequence(hands): hands = []

        farmer_pos = (farmer[0],farmer[1])
        if not _in_bounds(tiles,farmer_pos[0],farmer_pos[1]): return _pass()

        unit_positions = [farmer_pos]
        for h in hands:
            if _is_sequence(h) and len(h)>=2: unit_positions.append((h[0],h[1]))
            else: unit_positions.append((0,0))

        if hour == 0:
            _GROUP_ASSIGNMENTS.clear()
            assigned_workers = set()
            for group_name, tile_list in CORNER_GROUPS.items():
                sample_tile = tile_list[0]
                if not _in_bounds(tiles, sample_tile[0], sample_tile[1]):
                    continue
                tile_value = tiles[sample_tile[1]][sample_tile[0]]
                if tile_value == "LOCKED":
                    continue   

                best_idx = -1
                best_dist = 999
                for idx, upos in enumerate(unit_positions):
                    if idx == 0: continue          
                    if idx in assigned_workers:
                        continue
                    min_dist = min(_manhattan(upos, t) for t in tile_list)
                    if min_dist < best_dist:
                        best_dist = min_dist
                        best_idx = idx
                if best_idx != -1:
                    _GROUP_ASSIGNMENTS[group_name] = best_idx
                    assigned_workers.add(best_idx)

        shed = _safe_get(private,"shed",{})
        seeds = _safe_get(private,"seeds",{})
        inventories = _safe_get(private,"inventories",[])
        if not isinstance(inventories,list): inventories = []

        market_info = _safe_get(obs,"market",{})
        market_inv = _safe_get(market_info,"inventory",{})

        global_inv = {}
        for k,v in shed.items(): global_inv[k] = global_inv.get(k,0) + _int(v,0)
        for inv in inventories:
            if isinstance(inv,dict):
                for k,v in inv.items(): global_inv[k] = global_inv.get(k,0) + _int(v,0)

        shed_total = sum(_int(v,0) for v in shed.values())
        shed_pressure = shed_total/100.0

        active_crops = _scan_active_crops(tiles)
        days_left = max(0,30-day)
        placed_animals = _count_placed_animals(tiles)

        planning_workers = max(len(unit_positions), _desired_hands(day,money,active_crops,placed_animals)+1)
        expected_workers = planning_workers

        target_crops = _choose_target_crops(day,hour,money,seeds,active_crops,market_inv,
                                           planning_workers, unlocked_cnt)
        plant_budget = _plant_budget(target_crops,seeds,active_crops,planning_workers,unlocked_cnt)
        if hour >= 22:
            for c in list(plant_budget.keys()): plant_budget[c] = 0

        # Pass hour to generate_tasks for end-of-day fertilizer logic
        tasks = _generate_tasks(tiles,day,hour,target_crops,plant_budget,MAX_NEW_PLANTS_PER_TURN,
                               shed, inventories, unlocked_set, expected_workers)

        unit_actions, unit_types, unit_prios = _assign_tasks_zoned(
            tasks, unit_positions, tiles, unlocked_set, plant_budget, inventories,
            target_crops, seeds, _GROUP_ASSIGNMENTS, day)

        for i, upos in enumerate(unit_positions):
            x,y = upos
            if _in_bounds(tiles,x,y) and _is_weed(tiles[y][x]):
                if not PRIORITY_AWARE_WEED_OVERRIDE:
                    unit_actions[i] = ["DIG"]
                elif unit_prios[i] < WEED_OVERRIDE_CRITICAL_THRESHOLD:
                    unit_actions[i] = ["DIG"]

        # ------------------------------------------------------
        # MARKET ORDERS
        # ------------------------------------------------------
        buy_orders = []
        money_est = money

        if day == 0 and hour == 0:
            for i in range(OPENING_HIRE_COUNT):
                cost = _fib_cost(i)
                if money_est >= cost:
                    buy_orders.append(["HIRE"]); money_est -= cost
                else: break
            if money_est >= 1000:
                buy_orders.append(["BUY_ANIMAL","SHEEP",2]); money_est -= 1000
            if money_est >= 800:
                buy_orders.append(["BUY_ANIMAL","COW",2]); money_est -= 800
            if money_est >= 960:
                buy_orders.append(["BUY_SEED","MELON",12]); money_est -= 960
            if money_est >= 70:
                buy_orders.append(["BUY_SEED","WHEAT",7]); money_est -= 70
            if money_est >= 130:
                buy_orders.append(["BUY_PRODUCT","WHEAT",5]); money_est -= 130
        else:
            if day < LIQUIDATION_DAY and unlocked_cnt < MAX_QUADRANTS:
                if unlocked_cnt == 1 and money_est >= 1050:
                    buy_orders.append(["BUY_LAND"]); money_est -= 1000
                elif unlocked_cnt == 2 and money_est >= 2050:
                    buy_orders.append(["BUY_LAND"]); money_est -= 2000

            if ENABLE_ANIMALS and day<29 and placed_animals>0:
                wh = global_inv.get("WHEAT",0)
                target = placed_animals*2+3
                if wh < target:
                    deficit = min(10, target-wh)
                    est_cost = deficit*35
                    if money_est >= est_cost+100:
                        buy_orders.append(["BUY_PRODUCT","WHEAT",deficit])
                        money_est -= est_cost

            desired = _desired_hands(day,money_est,active_crops,placed_animals)
            already = hires_today
            while len(buy_orders)<7 and already < desired:
                cost = _fib_cost(already)
                if day<=3:
                    if money_est<cost: break
                elif day<=7:
                    if money_est<cost+10: break
                else:
                    if money_est<cost+50: break
                buy_orders.append(["HIRE"]); money_est-=cost; already+=1

            owned = placed_animals + global_inv.get("COW",0) + global_inv.get("SHEEP",0)
            if ENABLE_ANIMALS and day>=7 and owned<MAX_ANIMALS and len(buy_orders)<7:
                if money_est>=800+SAFE_MONEY_BUFFER and owned+2<=MAX_ANIMALS:
                    buy_orders.append(["BUY_ANIMAL","COW",2]); money_est-=800
                if (money_est>=1000+SAFE_MONEY_BUFFER and owned+4<=MAX_ANIMALS
                    and len(buy_orders)<7):
                    buy_orders.append(["BUY_ANIMAL","SHEEP",2]); money_est-=1000

            buy_crops = _phase_buy_crops(day)
            for crop in buy_crops:
                if len(buy_orders)>=7: break
                active = active_crops.get(crop,0)
                have = _int(_safe_get(seeds,crop,0),0)
                cap = _crop_cap(crop,planning_workers,unlocked_cnt)
                stock_tgt = SEED_TARGETS.get(crop,12)
                if active+have >= min(cap,stock_tgt): continue
                if days_left < MIN_PLANT_DAYS.get(crop,5): continue
                need = min(SEED_BATCHES.get(crop,8), min(cap,stock_tgt)-(active+have))
                seed_cost = SEED_COST.get(crop,10)*need
                if need>0 and money_est>=seed_cost+SAFE_MONEY_BUFFER:
                    buy_orders.append(["BUY_SEED",crop,need]); money_est-=seed_cost

        if day >= LIQUIDATION_DAY: buy_orders = []
        elif shed_pressure >= SHED_PRESSURE_LIMIT:
            buy_orders = [o for o in buy_orders
                         if o[0]=="BUY_LAND"
                         or (o[0]=="BUY_PRODUCT" and len(o)>1 and o[1]=="WHEAT")]

        sell_slots = max(0,10-len(buy_orders))
        endgame = day>=LIQUIDATION_DAY or shed_pressure>=SHED_PRESSURE_LIMIT

        daily_sold = _DAILY_SOLD
        if daily_sold["day"] != day:
            daily_sold.update({"day":day,"MELON":0,"STRAWBERRY":0,"MILK":0,"WOOL":0})

        sell_candidates = []
        for item in SELLABLE_ITEMS:
            qty = _sellable_inventory(item,shed,global_inv,day,placed_animals)
            if qty <= 0: continue
            mkt_inv = _int(_safe_get(market_inv, item, 10000), 10000)

            # Calculate actual expected revenue using dynamic pricing
            current_price = _get_price(item, mkt_inv)
            revenue = current_price * qty

            # Strategic limits to avoid price crashes
            sell_qty = qty
            if item in PREMIUM_ITEMS and mkt_inv >= 10000 + 50: 
                sell_qty = min(qty, 2)
            elif item == "CARROT" and mkt_inv >= 10000 + 400:
                sell_qty = min(qty, 2)

            if sell_qty > 0:
                sell_candidates.append((item, sell_qty, revenue))

        sell_candidates.sort(key=lambda x: x[2], reverse=True)
        sell_orders = [["SELL",item,qty] for item,qty,_ in sell_candidates[:sell_slots]]

        market = sell_orders + buy_orders
        final_market = []
        for order in market:
            if not _is_sequence(order) or len(order)==0: continue
            if order[0]=="SELL" and len(order)>=3:
                item,qty = order[1], _int(order[2],0)
                if _sellable_inventory(item,shed,global_inv,day,placed_animals) >= qty:
                    final_market.append(order)
            else:
                final_market.append(order)
        market = final_market[:10]

        farmer_action = unit_actions[0] if unit_actions else ["PASS"]
        hand_actions = unit_actions[1:] if len(unit_actions)>1 else []

        return {"farmer":farmer_action, "hands":hand_actions, "market":market}

    except Exception:
        return _pass()

